  const renderContributionHeatmap = (container, events = []) => { if (!container) return; const weeks = 18; const rows = 7; const width = weeks * 16 + 30; const height = rows * 16 + 24; const cells = []; for (let week = 0; week < weeks; week += 1) { for (let day = 0; day < rows; day += 1) { const index = week * rows + day; const event = events[index]; const level = event ? (event.type === 'PushEvent' ? 4 : event.type === 'PullRequestEvent' ? 3 : 2) : (index % 13 === 0 ? 1 : 0); const title = event ? `${event.type.replace('Event','')} · ${new Date(event.created_at).toLocaleDateString()}` : (isBn() ? 'এই দিনে public event নেই' : 'No public event on this day'); cells.push(`<rect class="github-heatmap__cell" data-level="${level}" x="${week * 16 + 22}" y="${day * 16 + 6}" width="11" height="11" rx="2"><title>${title}</title></rect>`); } } container.innerHTML = `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${isBn() ? 'Public GitHub activity heatmap' : 'Public GitHub activity heatmap'}"><text x="0" y="15" class="github-heatmap__label">${isBn() ? 'সাম্প্রতিক public activity' : 'Recent public activity'}</text>${cells.join('')}</svg>`; };
