  const refreshCurrentlyBuilding = async () => { if (!currentBuildStatus) return; try { const response = await fetch('https://api.github.com/users/MD-RASHIDUL-ISLAM-Dev/events/public?per_page=5', { headers: { Accept: 'application/vnd.github+json' } }); if (!response.ok) throw new Error('GitHub activity unavailable'); const events = await response.json(); const push = events.find(item => item.type === 'PushEvent' && item.repo?.name); if (push) { const repo = push.repo.name.split('/').pop(); currentBuildStatus.textContent = isBn() ? `${repo}-এ public update হয়েছে` : `Public update in ${repo}`; if (currentBuildMeta) currentBuildMeta.textContent = isBn() ? 'GitHub public activity · live snapshot' : 'GitHub public activity · live snapshot'; } } catch (error) { if (currentBuildMeta) currentBuildMeta.textContent = isBn() ? 'Manual update · active build' : 'Manual update · active build'; } };
  refreshCurrentlyBuilding();
  const simplifiedToggle = $('#simplified-toggle');
  const applySimplified = simple => { document.documentElement.dataset.view = simple ? 'simple' : 'full'; localStorage.setItem('rifat-simplified-view', String(simple)); if (simplifiedToggle) { simplifiedToggle.setAttribute('aria-pressed', String(simple)); simplifiedToggle.setAttribute('aria-label', simple ? (isBn() ? 'পূর্ণ ভিউ ব্যবহার করুন' : 'Use full view') : (isBn() ? 'সহজ ভিউ ব্যবহার করুন' : 'Use simplified view')); simplifiedToggle.textContent = simple ? (isBn() ? 'পূর্ণ' : 'Full') : (isBn() ? 'সহজ' : 'Simple'); } };
  simplifiedToggle?.addEventListener('click', () => applySimplified(document.documentElement.dataset.view !== 'simple'));
  applySimplified(localStorage.getItem('rifat-simplified-view') === 'true');

  /* Notes search and tag filtering */
  const notesSearch = $('#notes-search');
  const notesResultCount = $('#notes-result-count');
  const noteCards = $$('.note-card');
  let activeNoteTag = 'all';
  const renderNotes = () => {
    const query = String(notesSearch?.value || '').trim().toLowerCase();
    let visible = 0;
    noteCards.forEach(card => {
      const haystack = `${card.textContent} ${card.dataset.noteTags || ''}`.toLowerCase();
      const tagMatch = activeNoteTag === 'all' || (card.dataset.noteTags || '').split(',').includes(activeNoteTag);
      const queryMatch = !query || haystack.includes(query);
      const show = tagMatch && queryMatch;
      card.hidden = !show;
      if (show) visible += 1;
    });
    if (notesResultCount) notesResultCount.textContent = isBn() ? `${visible}টি নোট দেখানো হচ্ছে` : `${visible} note${visible === 1 ? '' : 's'} shown`;
  };
  notesSearch?.addEventListener('input', renderNotes);
  $$('.notes-tag').forEach(tag => tag.addEventListener('click', () => { activeNoteTag = tag.dataset.noteTag || 'all'; $$('.notes-tag').forEach(item => { const active = item === tag; item.classList.toggle('is-active', active); item.setAttribute('aria-pressed', String(active)); }); renderNotes(); }));
  renderNotes();

  /* Theme and language preferences */
  const themeToggle = $('#theme-toggle');
  const languageToggle = $('#language-toggle');
  const savedTheme = localStorage.getItem('rifat-theme');
  const applyTheme = theme => { document.documentElement.dataset.theme = theme; localStorage.setItem('rifat-theme', theme); if (themeToggle) { themeToggle.setAttribute('aria-pressed', String(theme === 'light')); themeToggle.setAttribute('aria-label', theme === 'light' ? 'Switch to dark theme' : 'Switch to light theme'); themeToggle.textContent = theme === 'light' ? '☾' : '☼'; } };
  applyTheme(savedTheme === 'light' ? 'light' : 'dark');
  themeToggle?.addEventListener('click', () => applyTheme(document.documentElement.dataset.theme === 'light' ? 'dark' : 'light'));
