  const runPerformanceScan = () => { const resources = performance.getEntriesByType('resource').filter(entry => entry.name.startsWith(window.location.origin)); const navigation = performance.getEntriesByType('navigation')[0]; const dcl = Math.round(navigation?.domContentLoadedEventEnd || 0); const requestNode = $('#budget-requests'); const status = $('#performance-scan-status'); if (requestNode) requestNode.textContent = `${resources.length} first-party resources · ${formatBytes(resources.reduce((sum, entry) => sum + (entry.decodedBodySize || 0), 0))} decoded`; if (status) status.textContent = isBn() ? `Local scan সম্পন্ন: ${resources.length}টি first-party resource, DOMContentLoaded প্রায় ${dcl}ms। এটি field-user benchmark নয়।` : `Local scan complete: ${resources.length} first-party resources, DOMContentLoaded about ${dcl}ms. This is not a field-user benchmark.`; document.dispatchEvent(new CustomEvent('rifat:track', { detail: { name: 'performance_scan' } })); };
